(window["webpackJsonp"]=window["webpackJsonp"]||[]).push([["propaganda"],{fb18:function(e,n,i){"use strict";i.r(n);var r=function(){var e=this,n=e.$createElement;e._self._c;return e._m(0)},s=[function(){var e=this,n=e.$createElement,i=e._self._c||n;return i("div",{staticClass:"container"},[i("h1",[e._v("Propaganda im Film")]),i("div",{staticClass:"page"},[i("h3",[e._v("Was ist Propaganda")]),e._v("\n      Besser ausformulieren: \n      - ist als sachliche Information (“Dokumentation”) getarnt\n      - emotionalisierende Suggestion,\n      - Appell an Grundbedürfnisse, Instinkte und/oder die Werte und Mythen der Gesellschaft,\n      - mangelnde Bezug zur Realität,\n      - Vereinfachung, die Abkürzung oder Auslassung der rationalen Analyse,\n      - Ausschaltung von Widerspruch, Zweifel und Dialog,\n      - Freund-Feind-Schema,\n      - Anspruch auf allgemeine Geltung\n      "),i("h3",[e._v("Manipulationstechniken")]),e._v("\n      - Was ist das? \n      - Quellen\n\n      "),i("h4",[e._v("Ästhetisierung")]),i("div",{staticClass:"description"},[e._v("Eigentlich hässliche oder grausame Sachverhalte werden in der Darstellung so bearbeitet, dass sie ästhetisch ansprechend und faszinierend erscheinen. Bildmaterial zu Kriegsereignissen wird so ausgewählt, dass die Realität des Krieges nicht wahrgenommen werden kann. „Erreicht wird dies beispielsweise durch den Einsatz von Licht, Farben, Musik, bestimmte Kameraeinstellungen, die Anordnung der Bildobjekte oder die Verwendung von gemeinhin als schön wahrgenommenen Bildmotiven aus Kunst, Natur, Alltag und Werbung.")]),i("div",{staticClass:"examples"},[e._v("\n        Beispiele im Film:\n        "),i("ul",[i("li",[e._v("...")]),i("li",[e._v("...")])])]),e._v("\n\n      Dekontextualisierung\n      Bei der Dekontextualisierung wird ein Nachrichteninhalt oder ein Ereignis aus seinem tatsächlichen Kontext herausgelöst, so dass das Ereignis nur für sich, also isoliert, wahrgenommen wird. Bei Ereignissen (zum Beispiel einer gewaltsamen Demonstration) fehlt die Vorgeschichte oder der politische Hintergrund. Das Ereignis oder die Nachricht kann daher nicht von Rezipienten eingeordnet und interpretiert werden. Zum richtigen Verständnis muss der ursprüngliche Kontext wiederhergestellt werden.\n\n      Kognitive Dissonanz\n      Menschen bevorzugen konsistente Vorstellungen, harmonische Konzepte, in denen alle Teile zueinander passen. Diese Tendenz kann manipulativ ausgenutzt werden. Nehmen wir an, ein Meinungsforscher stellt fest, dass eine bestimmte Gruppe von Menschen seinen Kandidaten für den Senator hasst, aber den Schauspieler A liebt. Sie verwenden die Billigung des Kandidaten A von ihrem Kandidaten, um die Meinung der Menschen zu ändern, weil die Menschen Inkonsistenz nicht tolerieren können. Sie sind gezwungen, den Schauspieler entweder nicht zu mögen oder den Kandidaten zu mögen. \n\n      Normaler Mensch\nMit dem Hinweis auf die „einfachen Leute“ oder „normalen Menschen“ wird versucht, das Publikum davon zu überzeugen, dass die Positionen des Propagandisten den gesunden Menschenverstand widerspiegeln. Es soll das Vertrauen des Publikums gewinnen, indem es auf die übliche Art und Weise des Zielpublikums kommuniziert. Propagandisten verwenden gewöhnliche Sprache und Verhaltensweisen (und kleiden ihre Botschaft in persönliche und audiovisuelle Kommunikation), um zu versuchen, ihren Standpunkt mit dem des Durchschnittsbürgers zu identifizieren. \n\nBerufung auf berühmte Menschen\nDiese Art von Propaganda beruft sich auf berühmte Menschen oder auf attraktive und glücklich erscheinende Menschen. \n\nÜbertreibung\nEine Übertreibung liegt vor, wenn Eigenschaften verstärkt, vergröbert und hervorgehoben werden, so dass die Wirklichkeit verzerrt erscheint.\n\nEuphorie\nDie Verwendung eines Ereignisses, das Euphorie oder Glück erzeugt, oder die Verwendung eines ansprechenden Ereignisses, um die Moral zu steigern. Euphorie kann erzeugt werden, indem ein Feiertag deklariert wird, Luxusartikel zur Verfügung gestellt werden oder eine Militärparade mit Marschbändern und patriotischen Botschaften aufgebaut wird.\n\nWiederholung\nDies ist die Wiederholung eines bestimmten Symbols oder Slogans, damit sich das Publikum daran erinnert. Dies kann in Form eines Jingle oder eines Bildes sein, das auf fast alles im Bild / in der Szene platziert wird. Dazu gehört auch die Verwendung von unterschwelligen Phrasen, Bildern oder anderen Inhalten in einer Propaganda.\n\nBerufung auf Autoritäten\nDie Berufung auf Autoritäten oder Experten zitieren oder berufen sich auf prominente Persönlichkeiten des öffentlichen Lebens, besonders auch Wissenschaftler, um Positionen, Ideen, Argumente oder Vorgehensweisen überzeugend, allgemeinverbindlich, vorbildlich oder wertvoll wirken zu lassen.\n\nHalbwahrheit\nEine halbe Wahrheit ist eine betrügerische Aussage, die ein gewisses Element der Wahrheit enthält. Es gibt verschiedene Formen: Die Aussage kann teilweise wahr sein, die Aussage kann völlig zutreffend sein, aber nur ein Teil der gesamten Wahrheit, oder sie kann ein betrügerisches Element verwenden, z die Wahrheit zu täuschen, ausweichen, beschuldigen oder falsch darstellen. \n\nRosinenpicken\nUnter diesem Begriff verbirgt sich eine Technik zur Steuerung der Wahrnehmung, in dem die Aufmerksamkeit des Publikums nur auf die herausgepickten Themen (Rosinen) gelenkt wird, während andere Themen gar nicht angesprochen werden. Unter Rosinenpicken versteht man somit die Auswahl der gewünschten Wahrheit und das Vermischen mit einigen Wahrheiten, die das Publikum hören möchte. \n    ")])])}],t=i("2877"),a={},d=Object(t["a"])(a,r,s,!1,null,null,null);n["default"]=d.exports}}]);
